import{R as e,e as o,f as i,U as n}from"./chunks/framework.ywem4qy5.js";const p=JSON.parse('{"title":"Twilio","description":"","frontmatter":{},"headers":[],"relativePath":"integrations/messaging/twilio.md","filePath":"integrations/messaging/twilio.md","lastUpdated":1775908585000}'),a={name:"integrations/messaging/twilio.md"};function r(l,t,s,h,g,c){return o(),i("div",null,[...t[0]||(t[0]=[n('<h1 id="twilio" tabindex="-1">Twilio <a class="header-anchor" href="#twilio" aria-label="Permalink to &quot;Twilio&quot;">​</a></h1><p>Follow the below steps to connect to the Twilio API.</p><h3 id="step-1-create-the-integration" tabindex="-1">Step 1. Create the Integration <a class="header-anchor" href="#step-1-create-the-integration" aria-label="Permalink to &quot;Step 1. Create the Integration&quot;">​</a></h3><ol><li>Navigate to <strong>Formie</strong> → <strong>Settings</strong> → <strong>Messaging</strong>.</li><li>Click the <strong>New Integration</strong> button.</li><li>Select <strong>Twilio</strong> as the <strong>Integration Provider</strong>.</li></ol><h3 id="step-2-connect-to-the-twilio-api" tabindex="-1">Step 2. Connect to the Twilio API <a class="header-anchor" href="#step-2-connect-to-the-twilio-api" aria-label="Permalink to &quot;Step 2. Connect to the Twilio API&quot;">​</a></h3><ol><li>Go to the <a href="https://www.twilio.com/console" target="_blank">Twilio Console</a> and log in.</li><li>Copy the <strong>Account SID</strong> from Twilio and paste in the <strong>Account SID</strong> field in Formie.</li><li>Copy the <strong>Auth Token</strong> from Twilio and paste in the <strong>Auth Token</strong> field in Formie.</li><li>Navigate to <strong>Phone Numbers</strong> → <strong>Manage</strong> → <strong>Active Numbers</strong>.</li><li>Select a Twilio phone number you own.</li><li>Paste this into the <strong>From Number</strong> field in Formie.</li></ol><h3 id="step-3-test-the-connection" tabindex="-1">Step 3. Test the Connection <a class="header-anchor" href="#step-3-test-the-connection" aria-label="Permalink to &quot;Step 3. Test the Connection&quot;">​</a></h3><ol><li>Save this integration.</li><li>Click on the <strong>Refresh</strong> button in the right-hand sidebar to verify the connection.</li></ol><h3 id="step-4-form-settings" tabindex="-1">Step 4. Form Settings <a class="header-anchor" href="#step-4-form-settings" aria-label="Permalink to &quot;Step 4. Form Settings&quot;">​</a></h3><ol><li>Go to the form you want to enable this integration on.</li><li>Click the <strong>Integrations</strong> tab.</li><li>In the left-hand sidebar, select the name you gave the integration.</li><li>Enable the integration and fill out all required fields.</li><li>Click <strong>Save</strong> to save the form.</li></ol>',10)])])}const m=e(a,[["render",r]]);export{p as __pageData,m as default};
